"use client";
import * as React from "react";
import { cn } from "../lib/cn";

export interface EntityDetail {
  icon?: React.ReactNode;
  label: React.ReactNode;
  /** Maakt van het detail een knop. */
  onClick?: () => void;
  href?: string;
}

export interface EntityHeaderProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  /** Avatar, logo of icoontegel links. */
  media?: React.ReactNode;
  title: React.ReactNode;
  /** Lichtere toevoeging achter de titel, bv. "V, 68j". */
  titleSuffix?: React.ReactNode;
  /** Regel onder de titel, bv. geboortedatum en nummers. */
  meta?: React.ReactNode;
  /** Badges of labels. */
  tags?: React.ReactNode;
  /** Contactgegevens of snelle links, rechts van de tags. */
  details?: EntityDetail[];
  /** Knoppen rechts. */
  actions?: React.ReactNode;
  /** Lijn onder de kop. */
  divider?: boolean;
  size?: "sm" | "md";
}

/**
 * EntityHeader — kop van een dossier, klant of patiënt: media, naam, kerngegevens,
 * labels, contactgegevens en acties in één blok dat netjes afbreekt op smalle schermen.
 */
export const EntityHeader = React.forwardRef<HTMLDivElement, EntityHeaderProps>(
  function EntityHeader(
    { media, title, titleSuffix, meta, tags, details, actions, divider = true, size = "md", className, children, ...rest },
    ref
  ) {
    return (
      <div
        ref={ref}
        className={cn(
          "pxui-entity",
          `pxui-entity-${size}`,
          divider && "pxui-entity-divider",
          className
        )}
        {...rest}
      >
        {media && <div className="pxui-entity-media">{media}</div>}

        <div className="pxui-entity-identity">
          <h1 className="pxui-entity-title">
            {title}
            {titleSuffix && <span className="pxui-entity-suffix">{titleSuffix}</span>}
          </h1>
          {meta && <div className="pxui-entity-meta">{meta}</div>}
        </div>

        {tags && <div className="pxui-entity-tags">{tags}</div>}

        {details && details.length > 0 && (
          <div className="pxui-entity-details">
            {details.map((detail, index) => {
              const content = (
                <>
                  {detail.icon && <span className="pxui-entity-detail-icon">{detail.icon}</span>}
                  {detail.label}
                </>
              );
              if (detail.href) {
                return (
                  <a key={index} className="pxui-entity-detail" href={detail.href}>
                    {content}
                  </a>
                );
              }
              if (detail.onClick) {
                return (
                  <button key={index} type="button" className="pxui-entity-detail" onClick={detail.onClick}>
                    {content}
                  </button>
                );
              }
              return (
                <span key={index} className="pxui-entity-detail pxui-entity-detail-static">
                  {content}
                </span>
              );
            })}
          </div>
        )}

        {actions && <div className="pxui-entity-actions">{actions}</div>}
        {children}
      </div>
    );
  }
);

/* ============================ EntityHeader ============================ */
.pxui-entity {
  display: flex; flex-wrap: wrap; align-items: flex-start; gap: 18px;
  margin-bottom: 20px; min-width: 0;
}
.pxui-entity-divider { padding-bottom: 20px; border-bottom: 1px solid var(--border); }

.pxui-entity-media { flex: none; }

.pxui-entity-identity { min-width: 220px; }
.pxui-entity-title {
  font-size: 25px; font-weight: 650; letter-spacing: -0.025em;
  line-height: 1.15; color: var(--text);
}
.pxui-entity-suffix {
  margin-left: 8px; font-size: var(--fs-base); font-weight: 500; color: var(--text-3);
  letter-spacing: 0;
}
.pxui-entity-meta { margin-top: 5px; font-size: 13px; color: var(--text-3); }

.pxui-entity-tags { display: flex; flex-wrap: wrap; gap: 7px; max-width: 460px; padding-top: 3px; }

.pxui-entity-details { display: flex; flex-direction: column; gap: 6px; }
.pxui-entity-detail {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 7px 10px; border: 1px solid var(--border); border-radius: var(--r-sm);
  background: var(--surface); color: var(--text-2);
  font: inherit; font-size: 13px; text-align: left; text-decoration: none;
  cursor: pointer; transition: background var(--dur-fast), border-color var(--dur-fast);
}
.pxui-entity-detail:hover { background: var(--surface-hover); border-color: var(--border-strong); }
.pxui-entity-detail:focus-visible { outline: none; box-shadow: var(--ring); }
.pxui-entity-detail-static { cursor: default; }
.pxui-entity-detail-static:hover { background: var(--surface); border-color: var(--border); }
.pxui-entity-detail-icon { display: inline-flex; color: var(--text-3); }
.pxui-entity-detail-icon svg { width: 15px; height: 15px; }

.pxui-entity-actions {
  margin-left: auto; display: flex; flex-wrap: wrap; align-items: center; gap: 10px;
}

/* ---------- Klein formaat ---------- */
.pxui-entity-sm { gap: 14px; margin-bottom: 16px; }
.pxui-entity-sm .pxui-entity-title { font-size: 19px; }
.pxui-entity-sm .pxui-entity-identity { min-width: 160px; }
.pxui-entity-sm .pxui-entity-divider { padding-bottom: 14px; }

@media (max-width: 720px) {
  .pxui-entity { gap: 14px; }
  .pxui-entity-actions { margin-left: 0; width: 100%; }
  .pxui-entity-actions > * { flex: 1; justify-content: center; }
  .pxui-entity-details { flex-direction: row; flex-wrap: wrap; }
}
